public int[][] Insert(int[][] ivs, int[] add) {
    var res = new List<int[]>();
    int i = 0, n = ivs.Length, s = add[0], e = add[1];
    while (i < n && ivs[i][1] < s) res.Add(ivs[i++]);   // целиком левее: конец до начала нового
    while (i < n && ivs[i][0] <= e) {                   // пересекается или касается: поглощаем
        s = Math.Min(s, ivs[i][0]);
        e = Math.Max(e, ivs[i][1]);
        i++;
    }
    res.Add(new[] { s, e });
    while (i < n) res.Add(ivs[i++]);                    // целиком правее
    return res.ToArray();
}
