public int EraseOverlapIntervals(int[][] intervals) {
    Array.Sort(intervals, (a, b) => a[1].CompareTo(b[1]));   // по концу
    int removed = 0, end = int.MinValue;
    foreach (var iv in intervals) {
        if (iv[0] >= end) end = iv[1];   // не пересекается с оставленными: берём, линия → его конец
        else removed++;                  // начинается раньше линии: удаляем
    }
    return removed;
}

