// звуки [start, end): сколько звучит в пике — столько AudioSource нужно в пуле
static int PeakVoices(float[] start, float[] end) {
    var s = (float[])start.Clone(); var e = (float[])end.Clone();  // офлайн-анализ: копии допустимы
    Array.Sort(s); Array.Sort(e);
    int playing = 0, peak = 0, j = 0;
    for (int i = 0; i < s.Length; i++) {
        while (j < e.Length && e[j] <= s[i]) { j++; playing--; }   // кончились к моменту s[i]
        playing++;
        peak = Math.Max(peak, playing);
    }
    return peak;
}
